func serveFile(dir, file string, c *Context) error {
	fs := http.Dir(dir)
	f, err := fs.Open(file)
	if err != nil {
		return NewHTTPError(http.StatusNotFound)
	}

	fi, err := f.Stat()
	if err != nil {
		return NewHTTPError(http.StatusNotFound)
	}
	if fi.IsDir() {
		return NewHTTPError(http.StatusForbidden)
	}

	http.ServeContent(c.response, c.request, fi.Name(), fi.ModTime(), f)
	return nil
}

