func (e *Echo) Start(address string) (err error) {
	if e.Server == nil {
		e.Server = &http.Server{Handler: e}
	}
	if e.Listener == nil {
		e.Listener, err = net.Listen("tcp", address)
		if err != nil {
			return
		}
		if e.TLSCertFile != "" && e.TLSKeyFile != "" {
			if !e.DisableHTTP2 {
				e.tlsConfig.NextProtos = append(e.tlsConfig.NextProtos, "h2")
			}
			e.tlsConfig.Certificates = make([]tls.Certificate, 1)
			e.tlsConfig.Certificates[0], err = tls.LoadX509KeyPair(e.TLSCertFile, e.TLSKeyFile)
			if err != nil {
				return
			}
			e.Listener = tls.NewListener(tcpKeepAliveListener{e.Listener.(*net.TCPListener)}, e.tlsConfig)
		} else {
			e.Listener = tcpKeepAliveListener{e.Listener.(*net.TCPListener)}
		}
	}
	return e.Server.Serve(e.Listener)
}

func (e *Echo) StartTLS(address string, certFile, keyFile string) (err error) {
	if e.TLSServer == nil {
		if e.Server == nil {
			e.TLSServer = &http.Server{Handler: e}
		} else {
			e.TLSServer = e.Server
		}
	}
	if e.TLSListener == nil {
		e.TLSListener, err = net.Listen("tcp", address)
		if err != nil {
			return
		}
		if certFile != "" && keyFile != "" {
			if !e.DisableHTTP2 {
				e.tlsConfig.NextProtos = append(e.tlsConfig.NextProtos, "h2")
			}
			e.tlsConfig.Certificates = make([]tls.Certificate, 1)
			e.tlsConfig.Certificates[0], err = tls.LoadX509KeyPair(certFile, keyFile)
			if err != nil {
				return
			}
			e.TLSListener = tls.NewListener(tcpKeepAliveListener{e.TLSListener.(*net.TCPListener)}, e.tlsConfig)
		} else {
			return errors.New("invalid TLS configuration")
		}
	}
	e.Logger.Printf(" ⇛ https server started on %v", e.Logger.Color().Green(e.TLSListener.Addr()))
	return e.TLSServer.Serve(e.TLSListener)
}

func (e *Echo) Shutdown(timeout time.Duration) {
	e.graceful.Stop(timeout)
}

func (e *Echo) ShutdownTLS(timeout time.Duration) {
	e.gracefulTLS.Stop(timeout)
}

func (e *Echo) config(gs *graceful.Server, s *http.Server, address string) {
	e.color.SetOutput(e.Logger.Output())
	gs.Server = s
	gs.Addr = address
	gs.Handler = e
	gs.Timeout = e.ShutdownTimeout
	gs.Logger = slog.New(e.Logger.Output(), e.Logger.Prefix()+": ", 0)
	if gs == e.gracefulTLS && !e.DisableHTTP2 {
		e.TLSConfig.NextProtos = append(e.TLSConfig.NextProtos, "h2")
	}
	// Global log
	slog.SetOutput(e.Logger.Output())
	slog.SetPrefix(e.Logger.Prefix() + ": ")
	slog.SetFlags(0)
}

func (e *Echo) StartAutoTLS() (err error) {
	address := ":443"
	e.config(e.gracefulTLS, e.TLSServer, address)
	e.TLSConfig.GetCertificate = e.tlsManager.GetCertificate
	if err = e.tlsManager.CacheFile(e.TLSCacheFile); err != nil {
		return
	}
	// NOTE: Added security
	e.tlsManager.SetHosts(e.TLSHosts)
	color.Printf(" ⇛ https auto tls server started on %s\n", color.Green(address))
	return e.gracefulTLS.ListenAndServeTLSConfig(e.TLSConfig)
}

